{"title": "Magnitude outliers (>= M5.63, 3 sigma)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "time",
      "index": "earthquakes-365d",
      "body": {
        "size": 1000,
        "runtime_mappings": {
          "mag_sigma": {
            "type": "double",
            "script": {
              "source": "if (doc['mag'].size() == 0) { return; } emit((doc['mag'].value - 1.7667484803909612) / 1.287189606155755);"
            }
          }
        },
        "fields": [
          "mag_sigma"
        ],
        "_source": [
          "time",
          "mag",
          "place",
          "depth"
        ],
        "sort": [
          {
            "time": "asc"
          }
        ]
      }
    },
    "format": {
      "property": "hits.hits"
    }
  },
  "transform": [
    {
      "calculate": "toDate(datum._source.time)",
      "as": "t"
    },
    {
      "calculate": "datum._source.mag",
      "as": "m"
    },
    {
      "calculate": "datum._source.place",
      "as": "place"
    },
    {
      "calculate": "datum.fields.mag_sigma[0]",
      "as": "z"
    }
  ],
  "mark": {
    "type": "circle",
    "opacity": 0.75
  },
  "encoding": {
    "x": {
      "field": "t",
      "type": "temporal",
      "title": null,
      "axis": {
        "format": "%b %y",
        "grid": false,
        "tickCount": {
          "interval": "month",
          "step": 1
        },
        "labelOverlap": "greedy"
      }
    },
    "y": {
      "field": "z",
      "type": "quantitative",
      "title": "Sigma above mean",
      "scale": {
        "domain": [
          2.9,
          5.0
        ],
        "nice": false
      }
    },
    "size": {
      "field": "m",
      "type": "quantitative",
      "title": "Mag",
      "scale": {
        "domain": [
          5.6,
          7.8
        ],
        "range": [
          25,
          320
        ]
      },
      "legend": {
        "orient": "right",
        "title": "Mag"
      }
    },
    "color": {
      "field": "m",
      "type": "quantitative",
      "scale": {
        "scheme": "yelloworangered",
        "domain": [
          5,
          7.8
        ]
      },
      "legend": null
    },
    "tooltip": [
      {
        "field": "place",
        "title": "Place"
      },
      {
        "field": "m",
        "title": "Magnitude"
      },
      {
        "field": "z",
        "title": "Sigma",
        "format": ".1f"
      },
      {
        "field": "t",
        "type": "temporal",
        "title": "Time"
      }
    ]
  }
}"}}

{"title": "Activity spikes (daily rate vs 2 sigma)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "index": "earthquakes-365d",
      "body": {
        "size": 0,
        "aggs": {
          "d": {
            "date_histogram": {
              "field": "time",
              "calendar_interval": "1d"
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.d.buckets"
    }
  },
  "transform": [
    {
      "calculate": "toDate(datum.key)",
      "as": "t"
    },
    {
      "calculate": "datum.doc_count",
      "as": "n"
    },
    {
      "joinaggregate": [
        {
          "op": "mean",
          "field": "n",
          "as": "mu"
        },
        {
          "op": "stdev",
          "field": "n",
          "as": "sd"
        }
      ]
    },
    {
      "calculate": "(datum.n - datum.mu) / datum.sd",
      "as": "z"
    },
    {
      "calculate": "datum.mu + 2 * datum.sd",
      "as": "thr"
    },
    {
      "calculate": "datum.z >= 2 ? 'spike' : 'normal'",
      "as": "cls"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "bar"
      },
      "encoding": {
        "x": {
          "field": "t",
          "type": "temporal",
          "title": null,
          "axis": {
            "format": "%b %y",
            "grid": false,
            "tickCount": {
              "interval": "month",
              "step": 1
            },
            "labelOverlap": "greedy"
          }
        },
        "y": {
          "field": "n",
          "type": "quantitative",
          "title": "Events / day"
        },
        "color": {
          "field": "cls",
          "type": "nominal",
          "title": null,
          "scale": {
            "domain": [
              "normal",
              "spike"
            ],
            "range": [
              "#8fa9c4",
              "#c0392b"
            ]
          }
        },
        "tooltip": [
          {
            "field": "t",
            "type": "temporal",
            "title": "Day"
          },
          {
            "field": "n",
            "title": "Events"
          },
          {
            "field": "z",
            "title": "Sigma above mean",
            "format": ".1f"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "rule",
        "strokeDash": [
          5,
          4
        ],
        "color": "#444"
      },
      "encoding": {
        "y": {
          "field": "thr",
          "type": "quantitative",
          "aggregate": "mean"
        }
      }
    }
  ]
}"}}

{"title": "Dense space-time cells (grid approximation)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "index": "earthquakes-365d",
      "body": {
        "size": 0,
        "aggs": {
          "w": {
            "date_histogram": {
              "field": "time",
              "fixed_interval": "7d"
            },
            "aggs": {
              "g": {
                "geotile_grid": {
                  "field": "location",
                  "precision": 8,
                  "size": 5
                },
                "aggs": {
                  "c": {
                    "geo_centroid": {
                      "field": "location"
                    }
                  },
                  "mx": {
                    "max": {
                      "field": "mag"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.w.buckets"
    }
  },
  "transform": [
    {
      "flatten": [
        "g.buckets"
      ],
      "as": [
        "cell"
      ]
    },
    {
      "calculate": "datum.cell.doc_count",
      "as": "n"
    },
    {
      "calculate": "datum.key_as_string",
      "as": "week"
    },
    {
      "calculate": "format(datum.cell.c.location.lat, '.1f') + ', ' + format(datum.cell.c.location.lon, '.1f')",
      "as": "where"
    },
    {
      "calculate": "datum.cell.mx.value",
      "as": "maxmag"
    },
    {
      "calculate": "substring(datum.key_as_string, 0, 10) + '  @ ' + datum.where",
      "as": "label"
    },
    {
      "window": [
        {
          "op": "rank",
          "as": "rk"
        }
      ],
      "sort": [
        {
          "field": "n",
          "order": "descending"
        }
      ]
    },
    {
      "filter": "datum.rk <= 20"
    }
  ],
  "mark": {
    "type": "bar"
  },
  "encoding": {
    "y": {
      "field": "label",
      "type": "nominal",
      "title": null,
      "sort": {
        "field": "n",
        "order": "descending"
      },
      "axis": {
        "labelLimit": 220
      }
    },
    "x": {
      "field": "n",
      "type": "quantitative",
      "title": "Events in cell"
    },
    "color": {
      "field": "maxmag",
      "type": "quantitative",
      "title": "Max mag",
      "scale": {
        "scheme": "yelloworangered"
      }
    },
    "tooltip": [
      {
        "field": "week",
        "title": "Week of"
      },
      {
        "field": "where",
        "title": "Centroid lat, lon"
      },
      {
        "field": "n",
        "title": "Events"
      },
      {
        "field": "maxmag",
        "title": "Max magnitude"
      }
    ]
  }
}"}}

